SELECT c.id, c.scene_id, s.name AS scene_name, c.title, c.created_time, c.updated_time
FROM ai_conversation c
LEFT JOIN ai_scene s ON c.scene_id = s.id
WHERE c.deleted = 0 AND c.user_id = #{userId}
AND c.scene_id = #{q.sceneId}

    AND c.title LIKE CONCAT('%', #{q.keyword}, '%')


    AND c.created_time >= #{q.startTime}


    AND c.created_time <= #{q.endTime}

ORDER BY c.updated_time DESC

SELECT c.id, c.scene_id, s.name AS scene_name, c.title, c.created_time, c.updated_time FROM ai_conversation c LEFT JOIN ai_scene s ON c.scene_id = s.id WHERE c.deleted = 0 AND c.user_id = #{q.userId} AND c.scene_id = #{q.sceneId}
AND c.title LIKE CONCAT('%', #{q.keyword}, '%')
ORDER BY c.updated_time DESC

mapper.update:
UPDATE ai_conversation
title = #{title}, deleted = #{deleted}, updated_time = NOW()
WHERE id = #{id}
